def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    # Find an interior, full, constant separator with equal-sized regions on both sides.
    for r in range(1, h-1):
        if len(set(grid[r])) == 1 and r == h-r-1:
            split = ('h', r)
            break
    if split is None:
        for c in range(1, w-1):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w-c-1:
                split = ('v', c)
                break
    if split is None:
        raise ValueError('No centered uniform separator')
    axis, k = split
    if axis == 'h':
        a, b = grid[:k], grid[k+1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    # Demonstrations use exactly one shared color between the panels; it is the mismatch fill.
    if len(common) != 1:
        raise ValueError(f'Expected one shared panel color, got {common}')
    fill = next(iter(common))
    return [[3 if a[r][c] == b[r][c] else fill for c in range(len(a[0]))] for r in range(len(a))]

